function CleveRoids.GetUnitCreatureID(unit)
    if not unit or not UnitExists(unit) then return nil end
    if UnitCreatureID then
        local id = UnitCreatureID(unit)
        if id and id > 0 then return id end
    end
    if C_CreatureInfo and C_CreatureInfo.GetCreatureID and UnitGUID then
        local guid = UnitGUID(unit)
        if guid then
            local id = C_CreatureInfo.GetCreatureID(guid)
            if id and id > 0 then return id end
        end
    end
    return nil
end

--- True for worldboss/rareelite, listed dungeon/raid bosses, or training dummies.
function CleveRoids.IsBossUnit(unit)
    if not unit or not UnitExists(unit) then return false end
    if UnitIsPlayer and UnitIsPlayer(unit) then return false end
    local cl = UnitClassification(unit)
    if cl == "worldboss" or cl == "boss" or cl == "rareelite" then
        return true
    end
    local id = CleveRoids.GetUnitCreatureID(unit)
    if id and CleveRoids.BossCreatureIDs[id] then
        return true
    end
    local name = UnitName(unit)
    if name then
        -- Exact match (zhCN) then lowercased (enUS); avoid lower-only on CJK.
        if CleveRoids.BossCreatureNames[name]
            or CleveRoids.BossCreatureNames[string.lower(name)] then
            return true
        end
    end
    return false
end

